/* Keep the SVG illustration lightweight; load the optional 3D scene on request. */
(function () {
  "use strict";
  const root = document.querySelector("[data-geometry-src]");
  if (!root) return;
  const toggle = root.querySelector("[data-motion-toggle]");
  toggle.hidden = false;
  toggle.textContent = "Play motion";
  toggle.setAttribute("aria-label", "Play geometry animation");
  toggle.removeAttribute("aria-pressed");
  toggle.addEventListener("click", function () {
    toggle.disabled = true;
    const script = document.createElement("script");
    script.src = root.dataset.geometrySrc;
    script.onload = function () {
      toggle.disabled = false;
      toggle.hidden = root.dataset.geometryState !== "ready";
    };
    script.onerror = function () { toggle.hidden = true; };
    document.head.appendChild(script);
  }, {once: true});
}());

/* The same document options control the live preview and the submitted PDF fields. */
(function () {
  "use strict";
  function init() {
    document.querySelectorAll("[data-pdf-document]").forEach(function (root) {
      const form = root.matches("form") ? root : root.querySelector("form");
      function refresh() {
        const authorInput = form.querySelector("[data-pdf-author-input]");
        const author = authorInput ? authorInput.value.trim() : (root.dataset.pdfAuthor || "");
        const authorPreview = root.querySelector("[data-pdf-preview-author]");
        const datePreview = root.querySelector("[data-pdf-preview-date]");
        const footer = root.querySelector("[data-pdf-preview-footer]");
        authorPreview.textContent = author;
        authorPreview.hidden = !form.querySelector("[data-pdf-show-author]").checked || !author;
        datePreview.textContent = root.dataset.pdfDate || "";
        datePreview.hidden = !form.querySelector("[data-pdf-show-date]").checked;
        footer.hidden = !form.querySelector("[data-pdf-show-footer]").checked;
      }
      form.addEventListener("input", refresh);
      form.addEventListener("change", refresh);
      refresh();
    });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init, {once: true});
  else init();
}());

/* Optional device recovery. Stored text is assigned to form controls, never HTML. */
(function (scope) {
  "use strict";
  const KEY = "asterproof.solution-writer.draft.v1";
  const TTL = 7 * 24 * 60 * 60 * 1000;
  const text = (value, limit) => typeof value === "string" && value.length <= limit;

  function validDocument(doc) {
    return doc && text(doc.title, 160) && text(doc.author_name, 100) && text(doc.problem_statement, 12000) &&
      ["pdf_show_author", "pdf_show_date", "pdf_show_footer"].every(key => typeof doc[key] === "boolean") &&
      Array.isArray(doc.blocks) && doc.blocks.length <= 32 && doc.blocks.every(block => block &&
        text(block.block_type, 30) && text(block.title, 300) && text(block.body_source, 12000) &&
        ["latex", "plain_text"].includes(block.body_format)) && JSON.stringify(doc).length <= 100000;
  }

  function decode(raw, now) {
    if (typeof raw !== "string" || raw.length > 400000) return null;
    try {
      const value = JSON.parse(raw);
      if (value.version !== 1 || !Number.isFinite(value.savedAt) || !Number.isFinite(value.expiresAt) ||
          value.savedAt > now + 60000 || value.expiresAt <= now || value.expiresAt <= value.savedAt ||
          value.expiresAt - value.savedAt > TTL || !validDocument(value.document)) return null;
      return value;
    } catch (_) { return null; }
  }

  function create(options) {
    const root = options.root.querySelector("[data-draft-recovery]");
    if (!root) return null;
    const enable = root.querySelector("[data-draft-enable]");
    const status = root.querySelector("[data-draft-status]");
    const offer = root.querySelector("[data-draft-offer]");
    const offerText = root.querySelector("[data-draft-offer-text]");
    const clear = root.querySelector("[data-draft-clear]");
    let knownRaw = null, awaitingRestore = false, timer;
    root.hidden = false;
    enable.disabled = false;

    function failed() {
      enable.checked = false;
      status.textContent = "Device storage is unavailable. Your writing is still open here; continue in your workspace or download a PDF.";
    }

    function load() {
      const raw = scope.localStorage.getItem(KEY);
      const saved = decode(raw, Date.now());
      knownRaw = raw;
      if (raw && !saved) {
        scope.localStorage.removeItem(KEY);
        knownRaw = null;
      }
      clear.hidden = !saved;
      awaitingRestore = Boolean(saved && JSON.stringify(saved.document) !== JSON.stringify(options.snapshot()));
      enable.checked = Boolean(saved && !awaitingRestore);
      offer.hidden = !awaitingRestore;
      if (awaitingRestore) {
        offerText.textContent = "Device draft available: " + (saved.document.title || "Untitled solution") +
          ". Restoring replaces the writing currently in this editor.";
        status.textContent = "Restore the device draft, or clear it before keeping a different draft.";
      } else {
        status.textContent = saved ? "Recovery copy saved on this device. It expires after seven days without edits." :
          "Device recovery is off. Your writing stays open in this tab.";
      }
      return saved;
    }

    function persist() {
      clearTimeout(timer);
      if (!enable.checked || awaitingRestore) return;
      const document = options.snapshot();
      if (!validDocument(document)) {
        status.textContent = "This draft is too large for device recovery. Your current writing is still here.";
        return;
      }
      try {
        // A stale tab must not replace a newer device draft.
        if (scope.localStorage.getItem(KEY) !== knownRaw) { load(); return; }
        const savedAt = Date.now();
        const raw = JSON.stringify({version: 1, savedAt, expiresAt: savedAt + TTL, document});
        scope.localStorage.setItem(KEY, raw);
        knownRaw = raw;
        clear.hidden = false;
        status.textContent = "Recovery copy saved on this device. It expires after seven days without edits.";
      } catch (_) { failed(); }
    }

    function remove() {
      clearTimeout(timer);
      try {
        scope.localStorage.removeItem(KEY);
        knownRaw = null;
        awaitingRestore = false;
        enable.checked = false;
        offer.hidden = true;
        clear.hidden = true;
        status.textContent = "Device draft cleared. Your current writing is still open here.";
      } catch (_) { failed(); }
    }

    enable.addEventListener("change", function () {
      if (!enable.checked) { remove(); return; }
      if (awaitingRestore) {
        enable.checked = false;
        status.textContent = "Restore or clear the existing device draft first. Your current writing has not replaced it.";
        return;
      }
      persist();
    });
    clear.addEventListener("click", remove);
    root.querySelector("[data-draft-restore]").addEventListener("click", function () {
      try {
        const saved = load();
        if (!saved) return;
        options.restore(saved.document);
        awaitingRestore = false;
        offer.hidden = true;
        enable.checked = true;
        persist();
      } catch (_) { failed(); }
    });
    scope.addEventListener("storage", function (event) {
      if (event.key !== KEY && event.key !== null) return;
      clearTimeout(timer);
      try { load(); } catch (_) { failed(); }
    });
    scope.addEventListener("pagehide", persist);
    try { load(); } catch (_) { failed(); }
    return {
      changed: function () { clearTimeout(timer); timer = setTimeout(persist, 250); },
      flush: persist,
    };
  }

  scope.AsterProofDraftRecovery = {create};
  if (typeof module !== "undefined" && module.exports) module.exports = {decode, validDocument, create, KEY, TTL};
}(typeof window === "undefined" ? globalThis : window));

/* Public solution blocks: local recovery is optional; handoff and PDF post current fields. */
(function () {
  "use strict";
  const root = document.querySelector("[data-solution-preview]");
  if (!root) return;
  const form = document.getElementById("solution-preview-form");
  const list = document.getElementById("preview-block-list");
  const total = document.getElementById("id_blocks-TOTAL_FORMS");
  const template = document.getElementById("preview-block-empty-form");
  const add = document.getElementById("preview-add-block");
  const preview = document.getElementById("converter-block-preview");
  const statement = document.getElementById("converter-statement");
  const status = document.getElementById("converter-preview-status");
  let timer;
  let recovery;
  let pending = Promise.resolve();

  function blocks() {
    return Array.from(list.querySelectorAll("[data-block-form]")).filter(function (block) {
      return !block.querySelector('[name$="-DELETE"]').checked;
    });
  }

  function refresh() {
    list.querySelectorAll("[data-block-form]").forEach(function (block) {
      const removed = block.querySelector('[name$="-DELETE"]').checked;
      block.hidden = removed;
      block.classList.toggle("d-none", removed);
    });
    const rows = blocks();
    rows.forEach(function (block, index) {
      block.querySelector("[data-block-number]").textContent = String(index + 1).padStart(2, "0");
      block.querySelector('[name$="-ORDER"]').value = index + 1;
      block.querySelector('[data-move-block="up"]').disabled = index === 0;
      block.querySelector('[data-move-block="down"]').disabled = index === rows.length - 1;
    });
    add.disabled = rows.length >= Number(root.dataset.blockLimit);
  }

  function snapshot() {
    const document = {};
    ["title", "author_name", "problem_statement"].forEach(key => { document[key] = form.elements[key].value; });
    ["pdf_show_author", "pdf_show_date", "pdf_show_footer"].forEach(key => { document[key] = form.elements[key].checked; });
    document.blocks = blocks().slice().sort((a, b) => Number(a.querySelector('[name$="-ORDER"]').value) -
      Number(b.querySelector('[name$="-ORDER"]').value)).map(function (block) {
      const values = {};
      ["block_type", "title", "body_format", "body_source"].forEach(key => {
        values[key] = block.querySelector('[name$="-' + key + '"]').value;
      });
      return values;
    });
    return document;
  }

  function restore(document) {
    ["title", "author_name", "problem_statement"].forEach(key => { form.elements[key].value = document[key]; });
    ["pdf_show_author", "pdf_show_date", "pdf_show_footer"].forEach(key => { form.elements[key].checked = document[key]; });
    list.replaceChildren();
    document.blocks.forEach(function (values, index) {
      const holder = window.document.createElement("div");
      holder.innerHTML = template.innerHTML.replace(/__prefix__/g, index);
      const block = holder.firstElementChild;
      ["block_type", "title", "body_format", "body_source"].forEach(key => {
        block.querySelector('[name$="-' + key + '"]').value = values[key];
      });
      list.appendChild(block);
    });
    total.value = document.blocks.length;
    refresh();
    form.dispatchEvent(new Event("change", {bubbles: true}));
    render();
  }

  function render() {
    pending = pending.then(async function () {
      if (window.AsterProofMathReady) await window.AsterProofMathReady;
      const math = window.MathJax;
      if (math && math.startup && math.startup.promise) await math.startup.promise;
      if (math && math.typesetClear) math.typesetClear([preview, statement]);
      document.getElementById("converter-document-title").textContent = form.elements.title.value || "My solution";
      statement.textContent = form.elements.problem_statement.value;
      statement.hidden = !statement.textContent.trim();
      preview.replaceChildren();
      const targets = [statement];
      const rows = blocks().slice().sort(function (left, right) {
        return Number(left.querySelector('[name$="-ORDER"]').value) - Number(right.querySelector('[name$="-ORDER"]').value);
      });
      rows.forEach(function (block) {
        const type = block.querySelector('[name$="-block_type"]');
        const heading = block.querySelector('[name$="-title"]').value;
        const body = block.querySelector('[name$="-body_source"]').value;
        const plainText = block.querySelector('[name$="-body_format"]').value === "plain_text";
        const section = document.createElement("section");
        section.className = "converter-preview-block";
        if (type.value && type.value !== root.dataset.plainBlockType) {
          const label = type.selectedOptions[0].textContent;
          const title = document.createElement("h3");
          title.textContent = label + (heading ? " · " + heading : "");
          section.appendChild(title);
          if (!plainText) targets.push(title);
        }
        const content = document.createElement("div");
        content.className = "converter-preview-body";
        content.textContent = body;
        section.appendChild(content);
        preview.appendChild(section);
        if (!plainText) targets.push(content);
      });
      if (math && math.typesetPromise) {
        await math.typesetPromise(targets);
        status.textContent = "Up to date";
      } else {
        status.textContent = "Text preview";
      }
    }).catch(function () {
      status.textContent = "Preview unavailable · your text is still here";
    });
  }

  function schedule() {
    clearTimeout(timer);
    timer = setTimeout(render, 180);
    if (recovery) recovery.changed();
  }

  add.hidden = false;
  add.addEventListener("click", function () {
    if (blocks().length >= Number(root.dataset.blockLimit)) return;
    const removed = Array.from(list.querySelectorAll("[data-block-form]")).find(function (block) {
      return block.querySelector('[name$="-DELETE"]').checked;
    });
    const index = removed ? removed.querySelector('[name$="-DELETE"]').name.split("-")[1] : total.value;
    const holder = document.createElement("div");
    holder.innerHTML = template.innerHTML.replace(/__prefix__/g, index);
    const block = holder.firstElementChild;
    if (removed) removed.remove();
    else total.value = Number(total.value) + 1;
    list.appendChild(block);
    refresh(); schedule();
    block.querySelector('[name$="-body_source"]').focus();
  });

  list.addEventListener("click", function (event) {
    const button = event.target.closest("button");
    if (!button) return;
    const block = button.closest("[data-block-form]");
    if (!block) return;
    const rows = blocks(), index = rows.indexOf(block);
    if (button.hasAttribute("data-remove-block")) {
      block.querySelector('[name$="-DELETE"]').checked = true;
      block.hidden = true;
      block.classList.add("d-none");
    } else if (button.dataset.moveBlock) {
      const other = rows[index + (button.dataset.moveBlock === "up" ? -1 : 1)];
      if (!other) return;
      if (button.dataset.moveBlock === "up") list.insertBefore(block, other);
      else list.insertBefore(other, block);
    } else if (button.dataset.insertMath) {
      const input = block.querySelector('[name$="-body_source"]');
      const start = input.selectionStart, end = input.selectionEnd;
      const before = button.dataset.insertMath === "display" ? "\\[\n" : "$";
      const after = button.dataset.insertMath === "display" ? "\n\\]" : "$";
      input.setRangeText(before + input.value.slice(start, end) + after, start, end, "end");
      input.focus();
    } else return;
    refresh(); schedule();
  });

  form.addEventListener("input", schedule);
  form.addEventListener("change", schedule);
  form.addEventListener("submit", function (event) {
    if (recovery) recovery.flush();
    const pdfStatus = root.querySelector("[data-pdf-status]");
    const handoff = event.submitter && ["continue_workspace", "continue_signup"].includes(event.submitter.value);
    if (pdfStatus) pdfStatus.textContent = handoff ? "Carrying your writing into your workspace…" :
      "PDF requested. Keep this tab open until the download starts.";
    blocks().forEach(function (block) {
      const order = block.querySelector('[name$="-ORDER"]');
      if (!order.value) order.value = 1;
    });
  });
  Array.from(list.querySelectorAll("[data-block-form]")).sort(function (left, right) {
    return Number(left.querySelector('[name$="-ORDER"]').value) - Number(right.querySelector('[name$="-ORDER"]').value);
  }).forEach(function (block) { list.appendChild(block); });
  refresh();
  const startingDocument = JSON.stringify(snapshot());
  if (window.AsterProofDraftRecovery) recovery = window.AsterProofDraftRecovery.create({root, snapshot, restore});
  document.addEventListener("click", function (event) {
    const link = event.target.closest("a[href]");
    if (!link || event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    const url = new URL(link.href, window.location.href);
    if (url.origin !== window.location.origin) return;
    const signup = url.pathname === root.dataset.signupUrl;
    if (!signup && url.pathname !== root.dataset.loginUrl) return;
    if (JSON.stringify(snapshot()) === startingDocument && root.dataset.writerResumed !== "true") return;
    const button = root.querySelector(signup ? "[data-signup-handoff]" : "[data-workspace-handoff]");
    if (!button) return;
    event.preventDefault();
    form.requestSubmit(button);
  });
  let startupRenderQueued = false;
  function renderStartupPreview() {
    if (startupRenderQueued) return;
    startupRenderQueued = true;
    // Let MathJax's startup task finish before adding preview typesetting work.
    setTimeout(render, 0);
  }
  function initializePreview() {
    if (window.AsterProofMathReady) window.AsterProofMathReady.then(renderStartupPreview);
    else render(); // The lazy homepage still needs a text preview before math is requested.
  }
  document.addEventListener("asterproof:math-ready", renderStartupPreview, {once: true});
  if (document.readyState === "complete") initializePreview();
  else window.addEventListener("load", initializePreview, {once: true});
}());
